void Timer5_Initialize( void ) // Initializes timer 5.  Is used for display brightness settling.
{
    T4CONbits.T45 = 0; //T4 and T5 are 16 bit timers.
    T5CONbits.TCKPS = 3; //prescale at 256.
    IFS1bits.T5IF = 0; // Clear flag.
    IEC1bits.T5IE = 1; //Enable interrupt.
    T5CONbits.TON = 1; //Turn on timer.
    return;
    
}
void Snd_Disp_word(char snddata, int dc) // Sends 8 bit word to display driver, along with Data/Command Pin
{
   int m;
   
   //Send D/C bit first
   DISP_CLK = 0 ;
   DISP_DATA = 0 ;
   DISP_DATA = DISP_DATA | dc; 
   //This is how it was done in disp_low4.c
   DISP_CLK   = 0  ;
   DISP_CLK   = 0  ;
   DISP_CLK   = 1  ;  // clock hi
 
   //Bit bang the rest of snddata.
   for(m=0;m<8;m++)  // bits. ENSURE D7 is MSB and is sent first
    {
      DISP_CLK   = 0   ;

      if( snddata & 0x80 ) // data
       {
         DISP_DATA = 1 ;
       }
      else
       {
         DISP_DATA = 0 ;
       }

      DISP_CLK   = 0  ;
      DISP_CLK   = 0  ;
      DISP_CLK   = 1  ;  // clock hi

      snddata = snddata << 1 ; // shift up a bit
    }

   return ;
}

void Snd_bitmap(char *snddata, int dc) // Sends 8-bit word to display driver
{
    int m;
    unsigned char mask = 0x80;    // Start with MSB

    // Send D/C bit first
    DISP_CLK = 0;
    DISP_DATA = dc;
    DISP_CLK = 0;
    DISP_CLK = 0;
    DISP_CLK = 1;

    // Bit-bang the data (MSB first)
    for (m = 0; m < 8; m++)
    {
        DISP_CLK = 0;

        if ((*snddata) & mask)
            DISP_DATA = 1;
        else
            DISP_DATA = 0;

        DISP_CLK = 0;
        DISP_CLK = 0;
        DISP_CLK = 1;

        mask >>= 1;    // Move to the next bit
    }
}

void DrawOneDigit(unsigned char (*ones)[13])
{
    int i, j;

    /* Top blank rows */
 // OxoC -> 0x34
    for (i = 0; i < 12; i++)
    {
        for (j = 0; j < 128; j++)
            Snd_Disp_word(0x00, 1);
    }

    /* Digit rows */
    for (i = 0; i < 40; i++)
    {
        /* Left blank */
        for (j = 0; j < 58; j++)
            Snd_Disp_word(0x00, 1);

        /* Digit */
        for (j = 0; j < 13; j++)
            Snd_bitmap(&ones[i][j], 1);

        /* Right blank */
        for (j = 0; j < 57; j++)
            Snd_Disp_word(0x00, 1);
    }

    /* Bottom blank rows */
    for (i = 0; i < 12; i++)
    {
        for (j = 0; j < 128; j++)
            Snd_Disp_word(0x00, 1);
    }
}

void DrawTwoDigits(unsigned char (*tens)[13], unsigned char (*ones)[13])
{
    int i, j;

    /* Top blank rows */
    for (i = 0; i < 12; i++)
    {
        for (j = 0; j < 128; j++)
            Snd_Disp_word(0x00, 1);
    }

    /* Digit rows */
    for (i = 0; i < 40; i++)
    {
        /* Left blank */
        for (j = 0; j < 48; j++)
            Snd_Disp_word(0x00, 1);

        /* Tens digit */
        for (j = 0; j < 13; j++)
            Snd_bitmap(&tens[i][j], 1);

        /* Space between digits */
        for (j = 0; j < 6; j++)
            Snd_Disp_word(0x00, 1);

        /* Ones digit */
        for (j = 0; j < 13; j++)
            Snd_bitmap(&ones[i][j], 1);

        /* Right blank */
        for (j = 0; j < 48; j++)
            Snd_Disp_word(0x00, 1);
    }

    /* Bottom blank rows */
    for (i = 0; i < 12; i++)
    {
        for (j = 0; j < 128; j++)
            Snd_Disp_word(0x00, 1);
    }
}


